    "name": "005_align_security_user_ids.sql",
    "sql": "BEGIN;\n\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM security_events\n    UNION ALL\n    SELECT 1 FROM audit_logs\n    UNION ALL\n    SELECT 1 FROM staff_activity_logs\n    UNION ALL\n    SELECT 1 FROM auth_sessions\n    UNION ALL\n    SELECT 1 FROM password_reset_tokens\n  ) THEN\n    RAISE EXCEPTION\n      'Security tables are not empty; aborting automatic UUID -> BIGINT conversion';\n  END IF;\nEND\n$$;\n\nALTER TABLE security_events\n  ALTER COLUMN user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nALTER TABLE audit_logs\n  ALTER COLUMN actor_user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nALTER TABLE audit_logs\n  ALTER COLUMN target_user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nALTER TABLE staff_activity_logs\n  ALTER COLUMN staff_user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nALTER TABLE auth_sessions\n  ALTER COLUMN user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nALTER TABLE password_reset_tokens\n  ALTER COLUMN user_id TYPE BIGINT\n  USING NULL::BIGINT;\n\nCOMMIT;\n"
